INSERT INTO material_translations (material_id, locale, title, description, body) VALUES ('82a8acb0-1584-42a3-816b-d3d279b9eef7','ro','Universul (partea a II-a) — galerie foto','Imagini care însoțesc lecția despre Sistemul Solar: Soarele, formarea sistemului, planetele, asteroizii, cometele și Luna.','{"captions":["Structura internă a Soarelui, de la nucleu la coroană","Coroana solară, vizibilă în timpul unei eclipse totale de Soare","Formarea Sistemului Solar dintr-un disc protoplanetar","Sistemul Solar — Soarele și cele opt planete","Centura de asteroizi, dintre Marte și Jupiter","Centura Kuiper, la marginea Sistemului Solar","O cometă, cu coada orientată dinspre Soare","Mercur","Venus","Terra","Luna","Fazele Lunii","Eclipsa de Soare și eclipsa de Lună (umbra și penumbra)","Marte, „planeta roșie”","Jupiter","Marea Pată Roșie a lui Jupiter","Saturn și inelele sale","Uranus","Neptun"]}');
